                            fontWeight: 700,
                            borderRadius: '8px'
                        }}>
                            Zur Bewertung
                        </Link>
                    </motion.div>

                    <motion.div 
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        transition={{ duration: 1, delay: 1.2 }}
                        style={{ marginTop: '4rem' }}
